-- ---------------------------------------------------------------------------
-- Permit types
-- Council standard days come from the 2024 service standard resolution: 20 business
-- days for residential, 30 for commercial. Accessory structures were set at 15 by
-- department policy rather than by the council.
-- ---------------------------------------------------------------------------

INSERT INTO permit_type (code, name, category, council_standard_days) VALUES
    ('BLD-RES-NEW',  'Residential new construction',              'residential', 20),
    ('BLD-RES-ALT',  'Residential alteration or addition',        'residential', 20),
    ('BLD-RES-ACC',  'Residential accessory structure',           'residential', 15),
    ('BLD-COM-NEW',  'Commercial new construction',               'commercial',  30),
    ('BLD-COM-ALT',  'Commercial alteration or tenant fit-out',   'commercial',  30);

