-- ---------------------------------------------------------------------------
-- SLA policies
-- The phase allowances sum to the council standard for each permit type.
-- Residential: 3 + 14 + 3 = 20. Accessory: 2 + 11 + 2 = 15. Commercial: 4 + 22 + 4 = 30.
-- ---------------------------------------------------------------------------

INSERT INTO sla_policy (permit_type_code, phase, discipline_code, allowance_days) VALUES
    ('BLD-RES-NEW', 'INTAKE_SCREENING', NULL, 3),
    ('BLD-RES-NEW', 'REVIEW_TASK',      NULL, 14),
    ('BLD-RES-NEW', 'PENDING_DECISION', NULL, 3),

    ('BLD-RES-ALT', 'INTAKE_SCREENING', NULL, 3),
    ('BLD-RES-ALT', 'REVIEW_TASK',      NULL, 14),
    ('BLD-RES-ALT', 'PENDING_DECISION', NULL, 3),

    ('BLD-RES-ACC', 'INTAKE_SCREENING', NULL, 2),
    ('BLD-RES-ACC', 'REVIEW_TASK',      NULL, 11),
    ('BLD-RES-ACC', 'PENDING_DECISION', NULL, 2),

    ('BLD-COM-NEW', 'INTAKE_SCREENING', NULL, 4),
    ('BLD-COM-NEW', 'REVIEW_TASK',      NULL, 22),
    ('BLD-COM-NEW', 'PENDING_DECISION', NULL, 4),

    ('BLD-COM-ALT', 'INTAKE_SCREENING', NULL, 4),
    ('BLD-COM-ALT', 'REVIEW_TASK',      NULL, 22),
    ('BLD-COM-ALT', 'PENDING_DECISION', NULL, 4);

-- Environmental review on commercial new construction gets a longer allowance because
-- stormwater modelling is slower than the other disciplines. A discipline-specific policy
-- overrides the NULL-discipline default for that phase.
INSERT INTO sla_policy (permit_type_code, phase, discipline_code, allowance_days) VALUES
    ('BLD-COM-NEW', 'REVIEW_TASK', 'ENVIRONMENTAL', 25);

